        feeWaived = feeCharged ? unpaidFee : fee;
        interestWaived = unpaidInterest;
    }
    if (earnsInterest && owed.signum() > 0) {
        charged = charged.add(interestOn(owed, daily, ChronoUnit.DAYS.between(from, today)));
    }
